fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    // It is assumed that dst, src, and mask all have the same length.
    // For each index i, select src[i] if mask[i] is true, else dst[i].
    let result = dst.into_iter()
        .zip(src.into_iter())
        .zip(mask.into_iter())
        .map(|((d, s), m)| if m { s } else { d })
        .collect();
    result
}